<template><view><view class="head"><text>你好，{{name}} 👋</text><small>{{today}} · 北京时间</small></view><view class="body"><view class="progress"><text>今日进度</text><strong>{{done}} / {{total}}</strong></view><view class="row"><text class="h">我的项目</text><button size="mini" @tap="newProject">新建项目</button></view><view v-if="!projects.length" class="empty">还没有项目，点击新建项目开始记录</view><view v-for="p in projects" :key="p.id" class="card" @tap="open(p.id)"><view><strong>{{p.name}}</strong><text>{{unfinished(p)}} 个未完成事项</text></view><text>查看 ›</text></view><view class="row"><text class="h">时间线</text></view><view v-for="r in records" :key="r.id" class="record"><text class="time">{{format(r.scheduled_at)}}</text><view><strong>{{r.title}}</strong><text>{{r.content||'暂无补充内容'}}</text><button size="mini" @tap="finish(r.id)">完成</button></view></view></view></view></template><script setup>import{ref,onMounted}from'vue';import{onShow}from'@dcloudio/uni-app';import{supabase,listProjects,listRecords,createProject,finishRecord,currentUser,configured}from'../../lib/supabase';const projects=ref([]),records=ref([]),name=ref('用户'),done=ref(0),total=ref(0),today=new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'short'}).format(new Date());onShow(load);async function load(){if(!configured)return uni.reLaunch({url:'/pages/login/login'});let u=await currentUser();if(!u)return uni.reLaunch({url:'/pages/login/login'});name.value=u.user_metadata.nickname||u.email;projects.value=await listProjects();records.value=await listRecords();total.value=projects.value.reduce((n,p)=>n+(p.records?.length||0),0);done.value=projects.value.reduce((n,p)=>n+(p.records?.filter(r=>r.done).length||0),0)}function unfinished(p){return p.records?.filter(r=>!r.done).length||0}function format(x){return new Date(x).toLocaleTimeString('zh-CN',{timeZone:'Asia/Shanghai',hour:'2-digit',minute:'2-digit'})}function open(id){uni.navigateTo({url:'/pages/project/detail?id='+id})}async function newProject(){uni.showModal({title:'新建项目',editable:true,placeholderText:'输入项目名称',success:async r=>{if(r.confirm&&r.content){await createProject({name:r.content,description:''});load()}}})}async function finish(id){await finishRecord(id);load()}</script><style scoped>.head{background:linear-gradient(150deg,#b9e6ff,#eaf8ff);padding:48px 22px 22px;display:flex;flex-direction:column}.head text{font-size:24px;font-weight:700}.head small{order:-1;color:#4b91b6;margin-bottom:7px}.body{padding:18px}.progress{padding:20px;background:#83cef5;border-radius:22px;display:flex;flex-direction:column}.progress strong{font-size:30px;margin-top:8px}.row{display:flex;justify-content:space-between;align-items:center;margin:24px 0 10px}.h{font-size:18px;font-weight:700}.row button{background:#e5f4fd;color:#398db8}.card{background:#fff;border:1px solid #e0edf5;border-radius:15px;padding:16px;margin-bottom:10px;display:flex;justify-content:space-between}.card view{display:flex;flex-direction:column}.card view text{font-size:12px;color:#8da0ad;margin-top:5px}.record{display:flex;gap:12px;margin-bottom:12px}.time{color:#87a0af;font-size:12px}.record view{flex:1;background:#fff;border-radius:15px;padding:14px;display:flex;flex-direction:column}.record view text{font-size:12px;color:#78909e;margin:6px 0}.record button{align-self:flex-start;background:#74c6f3;color:#fff}.empty{text-align:center;color:#8ca2af;padding:36px}</style>
